def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the solid 3 divider, horizontal or vertical.
    stripe_rows = [r for r in range(h) if all(grid[r][c] == 3 for c in range(w))]
    stripe_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    horizontal = bool(stripe_rows)

    if horizontal:
        stripe = set(stripe_rows)
        size = len(stripe_rows)
    else:
        stripe = set(stripe_cols)
        size = len(stripe_cols)

    step = size + 1
    row_starts = list(range(0, h - size + 1, step))
    col_starts = list(range(0, w - size + 1, step))

    # Get the repeated motif from any non-divider tile containing 2s.
    motif = None
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            overlaps = (any(r0 + k in stripe for k in range(size)) if horizontal
                        else any(c0 + k in stripe for k in range(size)))
            if overlaps:
                continue
            tile = [grid[r0 + dr][c0:c0 + size] for dr in range(size)]
            if any(v == 2 for row in tile for v in row):
                motif = tile
                break
        if motif is not None:
            break

    # Erase the divider.
    if horizontal:
        for r in stripe:
            out[r] = [0] * w
    else:
        for r in range(h):
            for c in stripe:
                out[r][c] = 0

    if motif is None:
        return out

    # Restore divider tiles when their indexed motif cell is 2.
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            overlaps = (any(r0 + k in stripe for k in range(size)) if horizontal
                        else any(c0 + k in stripe for k in range(size)))
            if overlaps and ri < size and ci < size and motif[ri][ci] == 2:
                for dr in range(size):
                    for dc in range(size):
                        out[r0 + dr][c0 + dc] = motif[dr][dc]

    # Mark each present tile at the motif cell indexed by its tile position.
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            if ri >= size or ci >= size:
                continue
            if any(out[r0 + dr][c0 + dc] == 2
                   for dr in range(size) for dc in range(size)):
                if motif[ri][ci] == 2:
                    out[r0 + ri][c0 + ci] = 8

    return out
